-- --------------------------------------------------------
-- Compatibilita export legacy -> modulo Express nativo
-- Questa sezione affianca lo schema legacy con le tabelle usate dal modulo
-- nativo del gestionale. Il collegamento del vecchio portale clienti non viene
-- migrato automaticamente perche il nuovo portale usa pickup_customers.
-- --------------------------------------------------------

SET @legacy_express_default_operatore_id := NULL;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS `clienti` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `ragione_sociale` varchar(160) NOT NULL DEFAULT '',
  `nome` varchar(80) NOT NULL DEFAULT '',
  `cognome` varchar(80) NOT NULL DEFAULT '',
  `cf_piva` varchar(32) DEFAULT NULL,
  `email` varchar(160) DEFAULT NULL,
  `telefono` varchar(40) DEFAULT NULL,
  `indirizzo` varchar(255) DEFAULT NULL,
  `note` text DEFAULT NULL,
  `morosita_flag` tinyint(1) NOT NULL DEFAULT 0,
  `morosita_score` enum('ok','attenzione','bloccato') NOT NULL DEFAULT 'ok',
  `morosita_note` text DEFAULT NULL,
  `morosita_aggiornato_il` datetime DEFAULT NULL,
  `morosita_fonte` varchar(100) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_clienti_ragione` (`ragione_sociale`),
  KEY `idx_clienti_morosita_score` (`morosita_score`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `configurazioni` (
  `chiave` varchar(120) NOT NULL,
  `valore` text DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`chiave`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `log_attivita` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `modulo` varchar(120) NOT NULL,
  `azione` varchar(160) NOT NULL,
  `dettagli` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_log_modulo` (`modulo`),
  KEY `idx_log_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `entrate_uscite` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `cliente_id` int(10) unsigned DEFAULT NULL,
  `tipo_movimento` enum('Entrata','Uscita') NOT NULL DEFAULT 'Entrata',
  `descrizione` varchar(180) NOT NULL,
  `listino_voce` varchar(180) DEFAULT NULL,
  `listino_costo_rivenditore` decimal(10,2) DEFAULT NULL,
  `listino_costo_cliente` decimal(10,2) DEFAULT NULL,
  `listino_margine` decimal(10,2) DEFAULT NULL,
  `riferimento` varchar(80) DEFAULT NULL,
  `metodo` varchar(60) NOT NULL DEFAULT 'Bonifico',
  `stato` varchar(40) NOT NULL DEFAULT 'In lavorazione',
  `importo` decimal(10,2) NOT NULL DEFAULT 0.00,
  `quantita` int(10) unsigned NOT NULL DEFAULT 1,
  `prezzo_unitario` decimal(10,2) NOT NULL DEFAULT 0.00,
  `data_scadenza` date DEFAULT NULL,
  `data_pagamento` date DEFAULT NULL,
  `note` text DEFAULT NULL,
  `allegato_path` varchar(255) DEFAULT NULL,
  `allegato_hash` char(64) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_entrate_uscite_cliente` (`cliente_id`),
  KEY `idx_entrate_uscite_stato` (`stato`),
  KEY `idx_entrate_uscite_scadenza` (`data_scadenza`),
  KEY `idx_entrate_uscite_pagamento` (`data_pagamento`),
  KEY `idx_entrate_uscite_cliente_stato` (`cliente_id`,`stato`),
  KEY `idx_entrate_uscite_tipo` (`tipo_movimento`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `servizi_express_operatori` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `nome` varchar(120) NOT NULL,
  `soglia_riordino` int(10) unsigned NOT NULL DEFAULT 10,
  `attivo` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_servizi_express_operatori_nome` (`nome`),
