  `stock_quantita` int(10) unsigned NOT NULL DEFAULT 0,
  `soglia_riordino` int(10) unsigned NOT NULL DEFAULT 0,
  `note` text DEFAULT NULL,
  `attivo` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_servizi_express_prodotti_sku` (`sku`),
  UNIQUE KEY `uniq_servizi_express_prodotti_imei` (`imei`),
  KEY `idx_servizi_express_prodotti_categoria` (`categoria`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `servizi_express_offerte` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `operatore_id` int(10) unsigned DEFAULT NULL,
  `titolo` varchar(150) NOT NULL,
