  `totale` decimal(10,2) NOT NULL DEFAULT 0.00,
  `iva` decimal(5,2) NOT NULL DEFAULT 22.00,
  `sconto` decimal(10,2) NOT NULL DEFAULT 0.00,
  `metodo_pagamento` varchar(60) NOT NULL DEFAULT 'Contanti',
  `stato` enum('Completata','Annullata','Rimborsata') NOT NULL DEFAULT 'Completata',
  `data_vendita` datetime NOT NULL,
  `note` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_servizi_express_vendite_cliente` (`cliente_id`),
  KEY `idx_servizi_express_vendite_user` (`user_id`),
  KEY `idx_servizi_express_vendite_data` (`data_vendita`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `servizi_express_iccid_stock` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `operatore_id` int(10) unsigned NOT NULL,
  `vendita_id` int(10) unsigned DEFAULT NULL,
  `iccid` varchar(32) NOT NULL,
  `stato` enum('InStock','Reserved','Sold') NOT NULL DEFAULT 'InStock',
  `note` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_servizi_express_iccid_stock_iccid` (`iccid`),
  KEY `idx_servizi_express_iccid_stock_operatore` (`operatore_id`),
  KEY `idx_servizi_express_iccid_stock_stato` (`stato`),
  KEY `idx_servizi_express_iccid_stock_vendita` (`vendita_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `servizi_express_vendita_righe` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `vendita_id` int(10) unsigned NOT NULL,
  `operatore_id` int(10) unsigned DEFAULT NULL,
  `iccid_stock_id` int(10) unsigned DEFAULT NULL,
  `prodotto_id` int(10) unsigned DEFAULT NULL,
  `offerta_id` int(10) unsigned DEFAULT NULL,
  `tipo` enum('sim','prodotto','servizio') NOT NULL DEFAULT 'sim',
  `descrizione` varchar(255) NOT NULL,
  `quantita` int(10) unsigned NOT NULL DEFAULT 1,
