CREATE TABLE IF NOT EXISTS `servizi_express_richieste` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `cliente_id` int(10) unsigned NOT NULL,
  `prodotto_id` int(10) unsigned DEFAULT NULL,
  `titolo` varchar(150) NOT NULL,
  `tipo_richiesta` enum('Purchase','Reservation','Deposit','Installment','Support') NOT NULL DEFAULT 'Purchase',
  `stato` enum('Pending','InReview','Confirmed','Completed','Cancelled','Declined') NOT NULL DEFAULT 'Pending',
  `importo_acconto` decimal(10,2) DEFAULT NULL,
  `numero_rate` int(10) unsigned DEFAULT NULL,
  `metodo_pagamento` varchar(60) DEFAULT NULL,
  `data_desiderata` date DEFAULT NULL,
  `note_cliente` text DEFAULT NULL,
  `nota_interna` text DEFAULT NULL,
  `gestita_da` int(11) DEFAULT NULL,
  `gestita_il` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_servizi_express_richieste_cliente` (`cliente_id`),
  KEY `idx_servizi_express_richieste_prodotto` (`prodotto_id`),
  KEY `idx_servizi_express_richieste_stato` (`stato`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

  `ragione_sociale`, `nome`, `cognome`, `cf_piva`, `email`, `telefono`, `indirizzo`, `note`, `created_at`, `updated_at`
)
SELECT
  '',
  TRIM(SUBSTRING_INDEX(TRIM(COALESCE(c.`fullname`, '')), ' ', 1)),
  TRIM(CASE
    WHEN INSTR(TRIM(COALESCE(c.`fullname`, '')), ' ') > 0 THEN SUBSTRING(TRIM(COALESCE(c.`fullname`, '')), INSTR(TRIM(COALESCE(c.`fullname`, '')), ' ') + 1)
    ELSE ''
  END),
  NULLIF(c.`tax_code`, ''),
  NULLIF(c.`email`, ''),
  NULLIF(c.`phone`, ''),
  NULL,
  CONCAT_WS('\n', NULLIF(c.`note`, ''), CONCAT('[LEGACY_EXPRESS_CUSTOMER_ID:', c.`id`, ']')),
  COALESCE(c.`created_at`, NOW()),
  COALESCE(c.`updated_at`, c.`created_at`, NOW())
FROM `customers` c
WHERE NOT EXISTS (
  SELECT 1
  FROM `clienti` cx
  WHERE cx.`note` COLLATE utf8mb4_unicode_ci LIKE CONCAT('%[LEGACY_EXPRESS_CUSTOMER_ID:', c.`id`, ']%') COLLATE utf8mb4_unicode_ci
);

  `ragione_sociale`, `nome`, `cognome`, `cf_piva`, `email`, `telefono`, `indirizzo`, `note`, `created_at`, `updated_at`
)
SELECT
  '',
  TRIM(SUBSTRING_INDEX(TRIM(s.`customer_name`), ' ', 1)),
  TRIM(CASE
    WHEN INSTR(TRIM(s.`customer_name`), ' ') > 0 THEN SUBSTRING(TRIM(s.`customer_name`), INSTR(TRIM(s.`customer_name`), ' ') + 1)
    ELSE ''
  END),
  NULL,
  NULL,
  NULL,
  NULL,
  CONCAT('[LEGACY_EXPRESS_SALE_NAME_MD5:', MD5(TRIM(s.`customer_name`)), ']'),
  COALESCE(MIN(s.`created_at`), NOW()),
  COALESCE(MAX(s.`created_at`), NOW())
FROM `sales` s
WHERE s.`customer_id` IS NULL
  AND NULLIF(TRIM(COALESCE(s.`customer_name`, '')), '') IS NOT NULL
  AND NOT EXISTS (
    SELECT 1
    FROM `clienti` cx
    WHERE cx.`note` COLLATE utf8mb4_unicode_ci LIKE CONCAT('%[LEGACY_EXPRESS_SALE_NAME_MD5:', MD5(TRIM(s.`customer_name`)), ']%') COLLATE utf8mb4_unicode_ci
  )
GROUP BY MD5(TRIM(s.`customer_name`)), TRIM(s.`customer_name`);

  `ragione_sociale`, `nome`, `cognome`, `cf_piva`, `email`, `telefono`, `indirizzo`, `note`, `created_at`, `updated_at`
)
SELECT '', 'Cliente', 'legacy Express', NULL, NULL, NULL, NULL, '[LEGACY_EXPRESS_ANON]', NOW(), NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1
  FROM `clienti`
  WHERE `note` LIKE '%[LEGACY_EXPRESS_ANON]%'
);

DROP TEMPORARY TABLE IF EXISTS `tmp_legacy_express_customer_map`;
CREATE TEMPORARY TABLE `tmp_legacy_express_customer_map` (
  `legacy_id` int(11) NOT NULL,
  `cliente_id` int(10) unsigned NOT NULL,
  PRIMARY KEY (`legacy_id`),
  KEY `idx_tmp_legacy_express_customer_map_cliente` (`cliente_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT c.`id`, cx.`id`
FROM `customers` c
INNER JOIN `clienti` cx
  ON cx.`note` COLLATE utf8mb4_unicode_ci LIKE CONCAT('%[LEGACY_EXPRESS_CUSTOMER_ID:', c.`id`, ']%') COLLATE utf8mb4_unicode_ci;

DROP TEMPORARY TABLE IF EXISTS `tmp_legacy_express_sale_name_map`;
CREATE TEMPORARY TABLE `tmp_legacy_express_sale_name_map` (
  `name_key` char(32) NOT NULL,
  `cliente_id` int(10) unsigned NOT NULL,
  PRIMARY KEY (`name_key`),
  KEY `idx_tmp_legacy_express_sale_name_map_cliente` (`cliente_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT MD5(TRIM(s.`customer_name`)), cx.`id`
FROM `sales` s
INNER JOIN `clienti` cx
  ON cx.`note` COLLATE utf8mb4_unicode_ci LIKE CONCAT('%[LEGACY_EXPRESS_SALE_NAME_MD5:', MD5(TRIM(s.`customer_name`)), ']%') COLLATE utf8mb4_unicode_ci
WHERE NULLIF(TRIM(COALESCE(s.`customer_name`, '')), '') IS NOT NULL
GROUP BY MD5(TRIM(s.`customer_name`)), cx.`id`;

SET @legacy_express_anon_cliente_id := (
  SELECT `id`
  FROM `clienti`
  WHERE `note` LIKE '%[LEGACY_EXPRESS_ANON]%'
  ORDER BY `id` DESC
  LIMIT 1
);

SELECT
  CASE p.`name`
    WHEN 'Fastweb' THEN 'Fastweb Mobile'
    WHEN 'Windtre' THEN 'WindTre'
    ELSE p.`name`
  END,
  GREATEST(COALESCE(p.`reorder_threshold`, 10), 1),
  1,
  COALESCE(p.`created_at`, NOW()),
  COALESCE(p.`created_at`, NOW())
FROM `providers` p
ON DUPLICATE KEY UPDATE
  `soglia_riordino` = VALUES(`soglia_riordino`),
  `attivo` = 1,
  `updated_at` = VALUES(`updated_at`);

SET @legacy_express_default_operatore_id := (
  SELECT `id`
  FROM `servizi_express_operatori`
  ORDER BY `id` ASC
  LIMIT 1
);

DROP TEMPORARY TABLE IF EXISTS `tmp_legacy_express_provider_map`;
CREATE TEMPORARY TABLE `tmp_legacy_express_provider_map` (
  `legacy_id` int(11) NOT NULL,
  `operatore_id` int(10) unsigned NOT NULL,
  PRIMARY KEY (`legacy_id`),
  KEY `idx_tmp_legacy_express_provider_map_operatore` (`operatore_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT p.`id`, so.`id`
FROM `providers` p
INNER JOIN `servizi_express_operatori` so
  ON so.`nome` COLLATE utf8mb4_unicode_ci = (CASE p.`name`
    WHEN 'Fastweb' THEN 'Fastweb Mobile'
    WHEN 'Windtre' THEN 'WindTre'
    ELSE p.`name`
  END) COLLATE utf8mb4_unicode_ci;

  `nome`, `sku`, `imei`, `categoria`, `prezzo`, `aliquota_iva`, `stock_quantita`, `soglia_riordino`, `note`, `attivo`, `created_at`, `updated_at`
)
SELECT
  p.`name`,
  NULLIF(p.`sku`, ''),
  NULLIF(p.`imei`, ''),
  NULLIF(p.`category`, ''),
  COALESCE(p.`price`, 0.00),
  COALESCE(NULLIF(p.`tax_rate`, 0.00), 22.00),
  GREATEST(COALESCE(p.`stock_quantity`, 0) - COALESCE(p.`stock_reserved`, 0), 0),
  GREATEST(COALESCE(p.`reorder_threshold`, 0), 0),
  CONCAT_WS('\n', NULLIF(p.`notes`, ''), CONCAT('[LEGACY_EXPRESS_PRODUCT_ID:', p.`id`, ']')),
  COALESCE(p.`is_active`, 1),
  COALESCE(p.`created_at`, NOW()),
  COALESCE(p.`updated_at`, p.`created_at`, NOW())
FROM `products` p
WHERE NOT EXISTS (
  SELECT 1
  FROM `servizi_express_prodotti` sp
  WHERE sp.`note` COLLATE utf8mb4_unicode_ci LIKE CONCAT('%[LEGACY_EXPRESS_PRODUCT_ID:', p.`id`, ']%') COLLATE utf8mb4_unicode_ci
);

DROP TEMPORARY TABLE IF EXISTS `tmp_legacy_express_product_map`;
CREATE TEMPORARY TABLE `tmp_legacy_express_product_map` (
  `legacy_id` int(11) NOT NULL,
  `prodotto_id` int(10) unsigned NOT NULL,
  PRIMARY KEY (`legacy_id`),
  KEY `idx_tmp_legacy_express_product_map_prodotto` (`prodotto_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT p.`id`, sp.`id`
FROM `products` p
INNER JOIN `servizi_express_prodotti` sp
  ON sp.`note` COLLATE utf8mb4_unicode_ci LIKE CONCAT('%[LEGACY_EXPRESS_PRODUCT_ID:', p.`id`, ']%') COLLATE utf8mb4_unicode_ci;

  `operatore_id`, `titolo`, `descrizione`, `prezzo`, `stato`, `valid_from`, `valid_to`, `created_at`, `updated_at`
)
SELECT
  pm.`operatore_id`,
  o.`title`,
  CONCAT_WS('\n', NULLIF(o.`description`, ''), CONCAT('[LEGACY_EXPRESS_OFFER_ID:', o.`id`, ']')),
  COALESCE(o.`price`, 0.00),
  o.`status`,
  o.`valid_from`,
  o.`valid_to`,
  COALESCE(o.`created_at`, NOW()),
  COALESCE(o.`updated_at`, o.`created_at`, NOW())
FROM `operator_offers` o
LEFT JOIN `tmp_legacy_express_provider_map` pm
  ON pm.`legacy_id` = o.`provider_id`
WHERE NOT EXISTS (
  SELECT 1
  FROM `servizi_express_offerte` so
  WHERE so.`descrizione` COLLATE utf8mb4_unicode_ci LIKE CONCAT('%[LEGACY_EXPRESS_OFFER_ID:', o.`id`, ']%') COLLATE utf8mb4_unicode_ci
);

DROP TEMPORARY TABLE IF EXISTS `tmp_legacy_express_sale_map`;
CREATE TEMPORARY TABLE `tmp_legacy_express_sale_map` (
  `legacy_id` int(11) NOT NULL,
  `vendita_id` int(10) unsigned NOT NULL,
  PRIMARY KEY (`legacy_id`),
  KEY `idx_tmp_legacy_express_sale_map_vendita` (`vendita_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

  `cliente_id`, `user_id`, `entrata_uscita_id`, `totale`, `iva`, `sconto`, `metodo_pagamento`, `stato`, `data_vendita`, `note`, `created_at`, `updated_at`
)
SELECT
  COALESCE(cm.`cliente_id`, snm.`cliente_id`, @legacy_express_anon_cliente_id),
  NULL,
  NULL,
  COALESCE(s.`total`, 0.00),
  COALESCE(s.`vat`, 22.00),
  COALESCE(s.`discount`, 0.00),
  COALESCE(s.`payment_method`, 'Contanti'),
  CASE s.`status`
    WHEN 'Cancelled' THEN 'Annullata'
    WHEN 'Refunded' THEN 'Rimborsata'
    ELSE 'Completata'
  END,
  COALESCE(s.`created_at`, NOW()),
  CONCAT_WS('\n', NULLIF(s.`customer_note`, ''), CONCAT('[LEGACY_EXPRESS_SALE_ID:', s.`id`, ']')),
  COALESCE(s.`created_at`, NOW()),
  COALESCE(s.`cancelled_at`, s.`refunded_at`, s.`created_at`, NOW())
FROM `sales` s
LEFT JOIN `tmp_legacy_express_customer_map` cm
  ON cm.`legacy_id` = s.`customer_id`
LEFT JOIN `tmp_legacy_express_sale_name_map` snm
  ON snm.`name_key` = MD5(TRIM(COALESCE(s.`customer_name`, '')))
WHERE NOT EXISTS (
  SELECT 1
  FROM `servizi_express_vendite` sv
  WHERE sv.`note` COLLATE utf8mb4_unicode_ci LIKE CONCAT('%[LEGACY_EXPRESS_SALE_ID:', s.`id`, ']%') COLLATE utf8mb4_unicode_ci
)
  AND COALESCE(cm.`cliente_id`, snm.`cliente_id`, @legacy_express_anon_cliente_id) IS NOT NULL;

SELECT s.`id`, sv.`id`
FROM `sales` s
INNER JOIN `servizi_express_vendite` sv
  ON sv.`note` COLLATE utf8mb4_unicode_ci LIKE CONCAT('%[LEGACY_EXPRESS_SALE_ID:', s.`id`, ']%') COLLATE utf8mb4_unicode_ci;

  `cliente_id`, `tipo_movimento`, `descrizione`, `listino_voce`, `metodo`, `stato`, `importo`, `quantita`, `prezzo_unitario`, `data_pagamento`, `note`, `created_at`, `updated_at`
)
SELECT
  sv.`cliente_id`,
  'Entrata',
  CONCAT('Vendita Express migrata #', s.`id`),
  NULLIF(s.`customer_name`, ''),
  sv.`metodo_pagamento`,
  CASE sv.`stato`
    WHEN 'Annullata' THEN 'Annullato'
    WHEN 'Rimborsata' THEN 'Rimborsato'
    ELSE 'Pagato'
  END,
  sv.`totale`,
  1,
  sv.`totale`,
  DATE(sv.`data_vendita`),
  CONCAT('[LEGACY_EXPRESS_SALE_ID:', s.`id`, ']'),
  sv.`created_at`,
  sv.`updated_at`
FROM `sales` s
INNER JOIN `tmp_legacy_express_sale_map` sm
  ON sm.`legacy_id` = s.`id`
INNER JOIN `servizi_express_vendite` sv
  ON sv.`id` = sm.`vendita_id`
WHERE NOT EXISTS (
  SELECT 1
  FROM `entrate_uscite` eu
  WHERE eu.`note` COLLATE utf8mb4_unicode_ci LIKE CONCAT('%[LEGACY_EXPRESS_SALE_ID:', s.`id`, ']%') COLLATE utf8mb4_unicode_ci
);

UPDATE `servizi_express_vendite` sv
INNER JOIN `sales` s
  ON sv.`note` COLLATE utf8mb4_unicode_ci LIKE CONCAT('%[LEGACY_EXPRESS_SALE_ID:', s.`id`, ']%') COLLATE utf8mb4_unicode_ci
INNER JOIN `entrate_uscite` eu
  ON eu.`note` COLLATE utf8mb4_unicode_ci LIKE CONCAT('%[LEGACY_EXPRESS_SALE_ID:', s.`id`, ']%') COLLATE utf8mb4_unicode_ci
SET sv.`entrata_uscita_id` = eu.`id`
WHERE sv.`entrata_uscita_id` IS NULL;

  `operatore_id`, `vendita_id`, `iccid`, `stato`, `note`, `created_by`, `created_at`, `updated_at`
)
SELECT
  COALESCE(pm.`operatore_id`, @legacy_express_default_operatore_id),
  sm.`vendita_id`,
  i.`iccid`,
  i.`status`,
  CONCAT_WS('\n', NULLIF(i.`notes`, ''), CONCAT('[LEGACY_EXPRESS_ICCID_ID:', i.`id`, ']')),
  NULL,
  COALESCE(i.`created_at`, NOW()),
  COALESCE(i.`updated_at`, i.`created_at`, NOW())
FROM `iccid_stock` i
LEFT JOIN `tmp_legacy_express_provider_map` pm
  ON pm.`legacy_id` = i.`provider_id`
LEFT JOIN (
  SELECT si1.`iccid_id`, MAX(si1.`id`) AS `max_sale_item_id`
  FROM `sale_items` si1
  WHERE si1.`iccid_id` IS NOT NULL
  GROUP BY si1.`iccid_id`
) latest_iccid_sale
  ON latest_iccid_sale.`iccid_id` = i.`id`
LEFT JOIN `sale_items` last_si
  ON last_si.`id` = latest_iccid_sale.`max_sale_item_id`
LEFT JOIN `tmp_legacy_express_sale_map` sm
  ON sm.`legacy_id` = last_si.`sale_id`
ON DUPLICATE KEY UPDATE
  `operatore_id` = VALUES(`operatore_id`),
  `vendita_id` = VALUES(`vendita_id`),
  `stato` = VALUES(`stato`),
  `note` = VALUES(`note`),
  `updated_at` = VALUES(`updated_at`);

  `vendita_id`, `operatore_id`, `iccid_stock_id`, `prodotto_id`, `offerta_id`, `tipo`, `descrizione`, `quantita`, `prezzo_unitario`, `aliquota_iva`, `totale_riga`, `sconto_riga`, `created_at`
)
SELECT
  sm.`vendita_id`,
  COALESCE(sei.`operatore_id`, sop.`operatore_id`, @legacy_express_default_operatore_id),
  sei.`id`,
  sp.`prodotto_id`,
  NULL,
  CASE
    WHEN si.`product_id` IS NOT NULL THEN 'prodotto'
    WHEN si.`iccid_id` IS NOT NULL THEN 'sim'
    ELSE 'servizio'
  END,
  COALESCE(NULLIF(si.`description`, ''), legacy_product.`name`, CONCAT('Riga legacy #', si.`id`)),
  GREATEST(COALESCE(si.`quantity`, 1), 1),
  COALESCE(si.`price`, 0.00),
  COALESCE(si.`tax_rate`, 0.00),
  ROUND(GREATEST(COALESCE(si.`quantity`, 1), 1) * COALESCE(si.`price`, 0.00), 2),
  0.00,
  COALESCE(sv.`created_at`, NOW())
FROM `sale_items` si
INNER JOIN `tmp_legacy_express_sale_map` sm
  ON sm.`legacy_id` = si.`sale_id`
INNER JOIN `servizi_express_vendite` sv
  ON sv.`id` = sm.`vendita_id`
LEFT JOIN `iccid_stock` legacy_iccid
  ON legacy_iccid.`id` = si.`iccid_id`
LEFT JOIN `servizi_express_iccid_stock` sei
  ON sei.`iccid` COLLATE utf8mb4_unicode_ci = legacy_iccid.`iccid` COLLATE utf8mb4_unicode_ci
LEFT JOIN `tmp_legacy_express_product_map` sp
  ON sp.`legacy_id` = si.`product_id`
LEFT JOIN `products` legacy_product
  ON legacy_product.`id` = si.`product_id`
LEFT JOIN `operator_offers` legacy_offer
  ON si.`product_id` IS NULL
 AND si.`description` IS NOT NULL
 AND (
        si.`description` COLLATE utf8mb4_unicode_ci = legacy_offer.`title` COLLATE utf8mb4_unicode_ci
     OR si.`description` COLLATE utf8mb4_unicode_ci LIKE CONCAT(legacy_offer.`title`, ' -%') COLLATE utf8mb4_unicode_ci
     OR si.`description` COLLATE utf8mb4_unicode_ci LIKE CONCAT(legacy_offer.`title`, '%') COLLATE utf8mb4_unicode_ci
 )
LEFT JOIN `tmp_legacy_express_provider_map` sop
  ON sop.`legacy_id` = legacy_offer.`provider_id`
WHERE NOT EXISTS (
  SELECT 1
  FROM `servizi_express_vendita_righe` svr
  WHERE svr.`vendita_id` = sm.`vendita_id`
    AND svr.`descrizione` COLLATE utf8mb4_unicode_ci = COALESCE(NULLIF(si.`description`, ''), legacy_product.`name`, CONCAT('Riga legacy #', si.`id`)) COLLATE utf8mb4_unicode_ci
    AND svr.`quantita` = GREATEST(COALESCE(si.`quantity`, 1), 1)
    AND svr.`prezzo_unitario` = COALESCE(si.`price`, 0.00)
);

  `cliente_id`, `prodotto_id`, `titolo`, `tipo_richiesta`, `stato`, `importo_acconto`, `numero_rate`, `metodo_pagamento`, `data_desiderata`, `note_cliente`, `nota_interna`, `gestita_da`, `gestita_il`, `created_at`, `updated_at`
)
SELECT
  cm.`cliente_id`,
  pm.`prodotto_id`,
  cpr.`product_name`,
  cpr.`request_type`,
  cpr.`status`,
  cpr.`deposit_amount`,
  CASE WHEN cpr.`installments` IS NULL OR cpr.`installments` <= 0 THEN NULL ELSE cpr.`installments` END,
  cpr.`payment_method`,
  cpr.`desired_pickup_date`,
  CONCAT_WS('\n', NULLIF(cpr.`note`, ''), NULLIF(CONCAT('Rif. bonifico: ', cpr.`bank_transfer_reference`), 'Rif. bonifico: ')),
  NULLIF(cpr.`handling_note`, ''),
  NULL,
  cpr.`handled_at`,
  COALESCE(cpr.`created_at`, NOW()),
  COALESCE(cpr.`updated_at`, cpr.`created_at`, NOW())
FROM `customer_product_requests` cpr
INNER JOIN `tmp_legacy_express_customer_map` cm
  ON cm.`legacy_id` = cpr.`customer_id`
LEFT JOIN `tmp_legacy_express_product_map` pm
  ON pm.`legacy_id` = cpr.`product_id`
WHERE NOT EXISTS (
  SELECT 1
  FROM `servizi_express_richieste` ser
  WHERE ser.`titolo` COLLATE utf8mb4_unicode_ci = cpr.`product_name` COLLATE utf8mb4_unicode_ci
    AND ser.`cliente_id` = cm.`cliente_id`
    AND ser.`created_at` = COALESCE(cpr.`created_at`, NOW())
);

  `cliente_id`, `prodotto_id`, `titolo`, `tipo_richiesta`, `stato`, `importo_acconto`, `numero_rate`, `metodo_pagamento`, `data_desiderata`, `note_cliente`, `nota_interna`, `gestita_da`, `gestita_il`, `created_at`, `updated_at`
)
SELECT
  cm.`cliente_id`,
  NULL,
  csr.`subject`,
  'Support',
  CASE csr.`status`
    WHEN 'Open' THEN 'Pending'
    WHEN 'InProgress' THEN 'InReview'
    WHEN 'Completed' THEN 'Completed'
    WHEN 'Cancelled' THEN 'Cancelled'
    ELSE 'Pending'
  END,
  NULL,
  NULL,
  NULL,
  DATE(csr.`preferred_slot`),
  CONCAT_WS('\n', CONCAT('Tipo legacy: ', csr.`type`), NULLIF(csr.`message`, '')),
  NULLIF(csr.`resolution_note`, ''),
  NULL,
  NULL,
  COALESCE(csr.`created_at`, NOW()),
  COALESCE(csr.`updated_at`, csr.`created_at`, NOW())
FROM `customer_support_requests` csr
INNER JOIN `tmp_legacy_express_customer_map` cm
  ON cm.`legacy_id` = csr.`customer_id`
WHERE NOT EXISTS (
  SELECT 1
  FROM `servizi_express_richieste` ser
  WHERE ser.`titolo` COLLATE utf8mb4_unicode_ci = csr.`subject` COLLATE utf8mb4_unicode_ci
    AND ser.`cliente_id` = cm.`cliente_id`
    AND ser.`created_at` = COALESCE(csr.`created_at`, NOW())
);

SELECT NULL, 'Servizi/Express', 'Compatibilita export legacy Express',
       JSON_OBJECT(
         'clienti_migrati', (SELECT COUNT(*) FROM `clienti` WHERE `note` LIKE '%[LEGACY_EXPRESS_CUSTOMER_ID:%' OR `note` LIKE '%[LEGACY_EXPRESS_SALE_NAME_MD5:%' OR `note` LIKE '%[LEGACY_EXPRESS_ANON]%'),
         'operatori_migrati', (SELECT COUNT(*) FROM `servizi_express_operatori`),
         'prodotti_migrati', (SELECT COUNT(*) FROM `servizi_express_prodotti` WHERE `note` LIKE '%[LEGACY_EXPRESS_PRODUCT_ID:%'),
         'offerte_migrate', (SELECT COUNT(*) FROM `servizi_express_offerte` WHERE `descrizione` LIKE '%[LEGACY_EXPRESS_OFFER_ID:%'),
         'vendite_migrate', (SELECT COUNT(*) FROM `servizi_express_vendite` WHERE `note` LIKE '%[LEGACY_EXPRESS_SALE_ID:%'),
         'richieste_migrate', (SELECT COUNT(*) FROM `servizi_express_richieste`)
       ),
       NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1
  FROM `log_attivita`
  WHERE `modulo` = 'Servizi/Express'
    AND `azione` = 'Compatibilita export legacy Express'
);

SET FOREIGN_KEY_CHECKS = 1;
